        handled = 1
    finally:
        finished = 2

def f():
    try:
        return 7
    finally:
        finished = 1

def f():
    try:
        raise ValueError("body")
    except ValueError:
        raise RuntimeError("handler")
    finally:
        finished = 1

def f():
    try:
        try:
            value = 1
        except ValueError:
            value = 2
        finally:
            inner_finished = 3
    except KeyError:
        outer_handled = 4
    finally:
        outer_finished = 5

def f(items):
    total = 0
    for item in items:
        try:
            if item == 0:
                break
            if item < 0:
                continue
            total += item
        finally:
            cleaned = item
    return total
